(5720269, 831767, 43774, '<td valign="top">A bit dull and washed out, looks over-exposed.</td>', 'A bit dull and washed out, looks over-exposed.', '2009-11-09 11:16:47.000000', NULL, 1),
(5720270, 831113, 16488, '<td valign="top">So nicely seen and selected! Wonderful abstract quality in the bluish lines against the unruly reds! ...and all the story is there too! Yes! That <i>is</i> what the end of summer looks like.</td>', 'So nicely seen and selected! Wonderful abstract quality in the bluish lines against the unruly reds! ...and all the story is there too! Yes! That is what the end of summer looks like.', '2009-11-09 11:17:06.000000', NULL, 1),
