INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5720283, 830062, 43774, '<td valign="top">Great detail and colour, I like that you filled the frame.</td>', 'Great detail and colour, I like that you filled the frame.', '2009-11-09 11:22:20.000000', NULL, 1),
(5720284, 832534, 43774, '<td valign="top">Beautiful, really nice.</td>', 'Beautiful, really nice.', '2009-11-09 11:22:22.000000', NULL, 1),
(5720292, 830269, 16488, '<td valign="top">Katerskill Falls! Thank you for taking me back to a place I loved to go so often so many years ago! Very painterly in the composition and rendering. Nicely done!</td>', 'Katerskill Falls! Thank you for taking me back to a place I loved to go so often so many years ago! Very painterly in the composition and rendering. Nicely done!', '2009-11-09 11:24:19.000000', NULL, 1),
(5720302, 829418, 16488, '<td valign="top">Very pretty! Like the way the leaves define the flat faces of the rocks.</td>', 'Very pretty! Like the way the leaves define the flat faces of the rocks.', '2009-11-09 11:35:14.000000', NULL, 1),
(5720307, 832407, 16488, '<td valign="top">I like this a lot! Dragging the camera really works in this image (so often, I think, it doesn''t). The light works like brush strokes. The abstraction keeps me looking, imagining grasses and tiny flowers one moment and the odd warmth of an autumn forest on a sunny day the next. Thank you!</td>', 'I like this a lot! Dragging the camera really works in this image (so often, I think, it doesn''t). The light works like brush strokes. The abstraction keeps me looking, imagining grasses and tiny flowers one moment and the odd warmth of an autumn forest on a sunny day the next. Thank you!', '2009-11-09 11:39:08.000000', NULL, 1),
(5720318, 832430, 16488, '<td valign="top">Love the painterly quality of this image. So classic!</td>', 'Love the painterly quality of this image. So classic!', '2009-11-09 11:49:21.000000', NULL, 1),
(5720319, 832243, 16488, '<td valign="top">I so want to bicycle down that path! How inviting!</td>', 'I so want to bicycle down that path! How inviting!', '2009-11-09 11:49:56.000000', NULL, 1),
(5720322, 831766, 16488, '<td valign="top">What a nice, moody take on this landscape! Such a melancholy feel to it.</td>', 'What a nice, moody take on this landscape! Such a melancholy feel to it.', '2009-11-09 11:51:22.000000', NULL, 1),
(5720323, 832430, 110023, '<td valign="top">Just a nice feeling to this picture. The black dog makes a great contrast and pulls all the colors together perfectly. I''m giving it a high score but I may come back and bump this up. I like it even more each time I look at it.</td>', 'Just a nice feeling to this picture. The black dog makes a great contrast and pulls all the colors together perfectly. I''m giving it a high score but I may come back and bump this up. I like it even more each time I look at it.', '2009-11-09 11:51:27.000000', NULL, 1),
(5720324, 832324, 110023, '<td valign="top">Cool! Beautiful color and style. Very nice :)</td>', 'Cool! Beautiful color and style. Very nice :)', '2009-11-09 11:51:29.000000', NULL, 1),
(5720325, 830228, 110023, '<td valign="top">Great catch! Very interesting subject. I had some of this stuff growing on my house and it is like wildfire. Beautiful photo! :)</td>', 'Great catch! Very interesting subject. I had some of this stuff growing on my house and it is like wildfire. Beautiful photo! :)', '2009-11-09 11:51:33.000000', NULL, 1),
(5720327, 831701, 16488, '<td valign="top">Love the texture and light of this image! Nice mini-scape!</td>', 'Love the texture and light of this image! Nice mini-scape!', '2009-11-09 11:52:25.000000', NULL, 1),
(5720328, 832591, 16488, '<td valign="top">Simply nice. Nicely simple.</td>', 'Simply nice. Nicely simple.', '2009-11-09 11:52:55.000000', NULL, 1),
(5720330, 832601, 16488, '<td valign="top">Zag!</td>', 'Zag!', '2009-11-09 11:53:24.000000', NULL, 1),
(5720334, 832586, 16488, '<td valign="top">Proof that autumn is everywhere! There''s a subtle motion to this image that I find very appealing. Nice.</td>', 'Proof that autumn is everywhere! There''s a subtle motion to this image that I find very appealing. Nice.', '2009-11-09 11:56:38.000000', NULL, 1),
(5720336, 831567, 16488, '<td valign="top">The image tells the story. I like it much.</td>', 'The image tells the story. I like it much.', '2009-11-09 11:57:25.000000', NULL, 1),
(5720340, 828430, 16488, '<td valign="top">Love the way the surface tension of the water outlines the leaf! For me, there''s also an interesting tension between abstraction of the leaves reflected and the defined representation of the floating leaf. Just nice!</td>', 'Love the way the surface tension of the water outlines the leaf! For me, there''s also an interesting tension between abstraction of the leaves reflected and the defined representation of the floating leaf. Just nice!', '2009-11-09 12:00:12.000000', NULL, 1),
(5720341, 832540, 16488, '<td valign="top">Wheeeeee! What a wonderfully garish combination of colors!</td>', 'Wheeeeee! What a wonderfully garish combination of colors!', '2009-11-09 12:00:45.000000', NULL, 1),
(5720345, 830954, 16488, '<td valign="top">It took me three times to love this... First, I thought, its orientation is "wrong." Then, I thought, what a rich mix of lily pads and leaves against a watery sky. Finally I stopped thinking and there it was!</td>', 'It took me three times to love this... First, I thought, its orientation is "wrong." Then, I thought, what a rich mix of lily pads and leaves against a watery sky. Finally I stopped thinking and there it was!', '2009-11-09 12:02:04.000000', NULL, 1),
