(5720755, 832283, 16488, '<td valign="top">How vein! ;)<br/>Seriously, I like the mottled tones and wandering paths of the leaf veins.</td>', 'How vein! ;)Seriously, I like the mottled tones and wandering paths of the leaf veins.', '2009-11-09 17:16:49.000000', NULL, 1),
(5720758, 831859, 20330, '<td valign="top">I love the colors. I would have stopped it down a bit more to open up the sharpness of the image, correcting the out of focus flowers in the foreground and sharpening the water drops. I do like the flowers/foliage mix tho =)</td>', 'I love the colors. I would have stopped it down a bit more to open up the sharpness of the image, correcting the out of focus flowers in the foreground and sharpening the water drops. I do like the flowers/foliage mix tho =)', '2009-11-09 17:22:03.000000', NULL, 1),
